@startuml

abstract class Person {
  + firstName : string
  + lastName : string
}

class Teacher extends Person {
  + email : string
}

class Student extends Person {}

class School {
  + name : string
}

class TeachingRelationship {
  + hours : int
}

class Room {
  + name : string
}

class ClassRoom extends Room {
  + capacity : int
}

class Gym extends Room {
  + sizeInSquareMeters : float
}

class ClassGroup {
  + name : string
}

School "1" -- "*" Teacher : employs
School "1" -- "1" principal : principal
Teacher "0..3" -- "*" School : teaches
Teacher "1" -- "0..1" principal : principal
TeachingRelationship "*" -- "1" Teacher
TeachingRelationship "*" -- "1" School
Student "*" -- "1" School : attends
Student "*" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" ClassRoom : assigned to
ClassGroup "10..31" -- "1" ClassGroup : forms

@enduml

